// 입력 검증·Idempotency-Key. 키 형식: {ticket_id}-111-{username}-lock (API-CONTRACT n8n 규칙 #46)
const b = $input.first().json;
const ctx = b.ctx;
if (b.action !== 'lock') return [{ json: { result: 'failed', detail: 'only lock is automated (해제·재설정은 사람이)', stop: true, ctx } }];
if (!b.username || !/^[A-Za-z0-9_.\-]{1,64}$/.test(b.username)) return [{ json: { result: 'failed', detail: 'bad_username', stop: true, ctx } }];
if (!b.ticket_id) return [{ json: { result: 'failed', detail: 'ticket_id required for Idempotency-Key', stop: true, ctx } }];
const idem = `${b.ticket_id}-111-${b.username}-lock`;
return [{ json: { action: 'lock', username: b.username, idem, url: 'http://10.250.0.2:5000/api/v1/response/accounts/lock', method: 'POST',
  dry_run: b.dry_run !== false, stop: false, ctx, requested_at: new Date().toISOString() } }];

const p = $input.first().json;
const t = new Date().toISOString();
return [{ json: { ok: false, result: p.result, detail: p.detail, applied_verified: false, requested_at: t, finished_at: t, ctx: p.ctx } }];

// dry_run: 포털을 부르지 않고 보낼 요청만 돌려준다. S4 username 잠금은 backend #3 병합·배포 뒤에야 실제 호출 가능.
const p = $input.first().json;
return [{ json: { ok: true, result: 'dry_run', detail: `would ${p.method} ${p.url}`, username: p.username, action: p.action, idempotency_key: p.idem,
  applied_verified: null, requested_at: p.requested_at, finished_at: new Date().toISOString(), ctx: p.ctx } }];

// 포털 응답을 결과 값으로 바꾼다(API-CONTRACT n8n 규칙 표). 시간 초과·연결 실패는 응답이 없다.
const j = $input.first().json;
const prev = $('요청 준비').first().json;
const status = j.statusCode ?? null;
const body = j.body ?? null;
let result = 'failed', retry = false, detail = '';
if (status === null) { retry = true; detail = 'timeout_or_network:' + String((j.error && j.error.message) || j.message || '').slice(0, 120); }
else if (status === 200) {
  const d = (body && body.data) || {};
  if (false) result = 'listed';
  else result = d.changed ? 'applied' : 'already_applied';
  detail = `${status} changed:${d.changed}`;
} else if (status === 403) { result = 'rejected'; detail = '403 FORBIDDEN'; }
else if (status === 409 || status >= 500) { retry = true; detail = `${status}`; }
else { detail = `${status} ${(body && body.error && body.error.code) || ''}`; }
return [{ json: { result, retry, detail, status, body_data: (body && body.data) || null, ctx: prev.ctx, idem: prev.idem, username: prev.username, action: prev.action,
  requested_at: prev.requested_at, finished_at: new Date().toISOString() } }];

