} else if (status === 403) { result = 'rejected'; detail = '403 FORBIDDEN'; }
else if (status === 409 || status >= 500) { retry = true; detail = `${status}`; }
else { detail = `${status} ${(body && body.error && body.error.code) || ''}`; }
return [{ json: { result, retry, detail, status, body_data: (body && body.data) || null, ctx: prev.ctx, idem: prev.idem, username: prev.username, action: prev.action,
  requested_at: prev.requested_at, finished_at: new Date().toISOString() } }];

const j = $input.first().json;
return [{ json: { ok: !['failed', 'rejected'].includes(j.result), result: j.result, detail: j.detail, username: j.username, action: j.action,
  idempotency_key: j.idem, applied_verified: null, requested_at: j.requested_at, finished_at: j.finished_at, ctx: j.ctx } }];
